<template><el-card><h3>任务进度</h3><el-button @click="load">刷新</el-button><el-table :data="jobs"><el-table-column prop="id" label="任务"/><el-table-column prop="status" label="状态"/><el-table-column prop="current" label="当前学号"/><el-table-column label="操作"><template #default="{row}"><el-button size="small" @click="action(row,'pause')">暂停</el-button><el-button size="small" @click="action(row,'resume')">继续</el-button><el-button size="small" type="danger" @click="action(row,'cancel')">中断</el-button></template></el-table-column></el-table></el-card></template><script setup>import{ref,onMounted}from"vue";const jobs=ref([]);async function load(){jobs.value=await(await fetch("/api/v1/jobs")).json()}async function action(j,a){await fetch('/api/v1/jobs/'+j.id+'/'+a,{method:'POST'});load()}onMounted(load)</script>